module freq_divbyfrac #(
    parameter MUL2_DIV_CLK = 7
) (
    input               rst_n,
    input               clk,
    output reg clk_div
);

reg [2:0] count;
reg clk_div_int;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        count <= 3'b000;
        clk_div_int <= 1'b0;
    end else begin
        if (count == MUL2_DIV_CLK - 1) begin
            count <= 3'b000;
            clk_div_int <= ~clk_div_int;
        end else begin
            count <= count + 1;
        end
    end
end

assign clk_div = clk_div_int;

endmodule
